    recomp_resume_table[0x8009FA08] = func_8009F988;
    recomp_resume_table[0x8009FA1C] = func_8009F988;
    recomp_entry_alias_table[0x80018008] = func_80017F64;
    recomp_entry_alias_table[0x8001C680] = func_8001C65C;
